import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.Dm8zwdB5.js";const l="/unified-filters/site/screenshots/panel-1.png",o="/unified-filters/site/screenshots/panel-2.png",m=JSON.parse('{"title":"Filters Panel","description":"","frontmatter":{},"headers":[],"relativePath":"components/filters-panel.md","filePath":"components/filters-panel.md","lastUpdated":1789395292000}'),r={name:"components/filters-panel.md"};function n(d,e,c,p,f,h){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="filters-panel" tabindex="-1">Filters Panel <a class="header-anchor" href="#filters-panel" aria-label="Permalink to &quot;Filters Panel&quot;">​</a></h1><p>The filters drilldown panel — now <strong>unified</strong> across every tool.</p><p>One consistent way to filter by status, assignee, location, dates, etc — whatever the tool tracks.</p><div class="shots"><img src="'+l+'" alt="Filters Panel screenshot 1"><img src="'+o+'" alt="Filters Panel screenshot 2"></div><h2 id="supported-filter-types" tabindex="-1">Supported filter types <a class="header-anchor" href="#supported-filter-types" aria-label="Permalink to &quot;Supported filter types&quot;">​</a></h2><p>Every filter in the panel is one of eight built-in types — feature teams pick which ones they need per filter, no custom UI required.</p><div class="tile-grid"><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=51391-14657&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Text</div><div class="tile-desc">Single/Multi-select from a list of text options, with optional avatars.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=51391-14046&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Members</div><div class="tile-desc">Single/Multi-select users, roles, or companies — configurable per filter.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=51391-12421&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Hierarchy</div><div class="tile-desc">Single/Multi-select tree-structured options (locations, categories) with cascading child selection.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=51391-13277&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Date</div><div class="tile-desc">Single date-option selection — presets or a custom range.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=51391-12425&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Status</div><div class="tile-desc">Single/Multi-select with badge styling per option.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=50738-11276&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Toggle</div><div class="tile-desc">A boolean switch or checkmark.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=50768-2579&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Input</div><div class="tile-desc">Free-form text, multiline, or numeric entry.</div></div></a><a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=53083-10053&amp;t=SOtsidakoVfoXS61-4"><div class="tile-card"><div class="tile-title">Conditional numeric input</div><div class="tile-desc">A comparison operator (=, ≠, &lt;, &gt;, between…), then one or two values.</div></div></a></div><p>The <a href="https://www.figma.com/design/oHi6w955NY5Uf4TpIyYLbJ/%E2%9D%96-ACC-DS-%7C-Mobile--iOS---Android-?node-id=50657-7277&amp;p=f&amp;t=ti99r5Tq3uhD6Zrh-0" target="_blank" rel="noreferrer">Filters Panel Figma file</a> is the design source of truth for every one of these types — see also <a href="./../reference/">Reference</a> for the rest of the source material.</p><h2 id="custom-fields" tabindex="-1">Custom Fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom Fields&quot;">​</a></h2><p>Custom fields are supported in the panel just like any built-in filter. Up to 10 (defaults to 10, configurable), they&#39;re displayed in-place alongside the rest; past that, a custom fields selection screen lets users choose which ones participate in filtering.</p><h2 id="reset-vs-clear-all" tabindex="-1">Reset vs. Clear All <a class="header-anchor" href="#reset-vs-clear-all" aria-label="Permalink to &quot;Reset vs. Clear All&quot;">​</a></h2><p>Two distinct actions:</p><div class="note-row"><b>Clear All</b> — clears every filter&#39;s selection back to empty. Shown whenever any filter is active, regardless of domain.</div><div class="note-row"><b>Reset</b> — restores the domain&#39;s original/default filter configuration, which may itself be non-empty (e.g. a default preset). Only shown for domains that opt into reset support — not every domain has a meaningful default to reset to.</div><h2 id="default-filter" tabindex="-1">Default filter <a class="header-anchor" href="#default-filter" aria-label="Permalink to &quot;Default filter&quot;">​</a></h2><p>Every domain can configure a <strong>default filter</strong> — the baseline set of filter values applied when a user has nothing saved yet, and restored by <strong>Reset</strong> (see above). It doesn&#39;t have to be empty: a domain can default to a meaningful preset (e.g. &quot;open items assigned to me&quot;) rather than &quot;no filters applied&quot; — once the user changes any filter, that change is saved like any other, the default is just the starting point.</p><h2 id="initial-filters" tabindex="-1">Initial Filters <a class="header-anchor" href="#initial-filters" aria-label="Permalink to &quot;Initial Filters&quot;">​</a></h2><p><span class="soon">Coming<br>soon<span class="hammer">🔨</span></span> A specific navigation route can also apply its own <strong>route-specific</strong> default filters, distinct from the domain-wide default above and never persisted — see <a href="./../integrations/initial-filters">Initial Filters</a> for the full design.</p><h2 id="filters-persistence" tabindex="-1">Filters persistence <a class="header-anchor" href="#filters-persistence" aria-label="Permalink to &quot;Filters persistence&quot;">​</a></h2><p>Every filter selection made in the panel is saved automatically — it survives app restarts and stays consistent with the rest of the framework, so users never lose their filters between sessions.</p>',20)])])}const v=t(r,[["render",n]]);export{m as __pageData,v as default};
